const D = { offset:.013, edge:.55, grain:.5, hue:200, energy:.6, speed:1, sat:80, style:'fringe', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W,H), cx = W/2, cy = H/2, dg = drawingContext;
const clamp = (v,a,b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const st = P.style;

// downsample buffers keyed on size
const md = 560, dsc = md / Math.max(W,H);
const bw = Math.max(2, Math.round(W*dsc)), bh = Math.max(2, Math.round(H*dsc));
const key = bw + 'x' + bh;
if (!S.buf || S.key !== key) {
  S.buf = createGraphics(bw, bh); S.scr = createGraphics(bw, bh);
  S.buf.colorMode(HSB,360,100,100,100); S.scr.colorMode(HSB,360,100,100,100);
  S.key = key;
}

const beatKick = clamp(K.pulse*.6 + A.bass*.9, 0, 1.4);
// offset breathes on real-time K.t (never re-phases) + beat + bass
const breathe = 0.6 + 0.4*Math.sin(K.t*1.4);
let ox = u * clamp(P.offset,0,0.09) * (0.4 + 0.9*beatKick + 0.5*breathe) * P.speed;
let oy = ox * 0.35 * Math.sin(K.t*0.7);
if (st === 'prism') ox *= 1.4;

// 1) capture the current scene into buf (downsampled)
try { S.buf.drawingContext.drawImage(dg.canvas, 0, 0, bw, bh); } catch(e) {}
const sx = ox*dsc, sy = oy*dsc;

// 2) reconstruct an RGB-split copy in scratch (tinted ADD copies — no filter())
const scx = S.scr.drawingContext;
S.scr.push();
S.scr.clear();
S.scr.blendMode(ADD);
S.scr.imageMode(CORNER);
if (st === 'prism') {
  // spectral smear: several hue-stepped copies fanned across the offset
  const cols = [[0,100],[40,100],[120,100],[190,100],[240,100],[300,90]];
  cols.forEach((c,i)=>{ const f=(i/(cols.length-1))-0.5; S.scr.tint(c[0],c[1],100,60); S.scr.image(S.buf, sx*f*2, sy*f*2); });
} else if (st === 'glitch') {
  // channel copies jump per horizontal band (seeded), harder shifts on the beat
  const bands = 7;
  for (let b=0;b<bands;b++){
    const y0 = Math.floor(b*bh/bands), y1 = Math.ceil((b+1)*bh/bands);
    const jitter = (fr(b + Math.floor(K.beat*2))*2-1) * (1 + 3*beatKick);
    scx.save(); scx.beginPath(); scx.rect(0,y0,bw,y1-y0); scx.clip();
    S.scr.tint(0,100,100,100);   S.scr.image(S.buf, sx*jitter, 0);
    S.scr.tint(120,100,100,100); S.scr.image(S.buf, 0, 0);
    S.scr.tint(240,100,100,100); S.scr.image(S.buf, -sx*jitter, 0);
    scx.restore();
  }
} else {
  // fringe / vhs / xray: clean R / G / B triad
  S.scr.tint(0,100,100,100);   S.scr.image(S.buf,  sx,  sy);
  S.scr.tint(120,100,100,100); S.scr.image(S.buf,  0,   0 );
  S.scr.tint(240,100,100,100); S.scr.image(S.buf, -sx, -sy);
}
if (st === 'xray') { // invert to a clinical negative
  scx.save(); scx.globalCompositeOperation = 'difference';
  scx.fillStyle = '#ffffff'; scx.fillRect(0,0,bw,bh); scx.restore();
}
// 3) edge-weight: keep the aberrated copy only toward the frame edge
const edge = clamp(P.edge, 0.05, 1);
scx.save();
scx.globalCompositeOperation = 'destination-in';
const r0 = Math.hypot(bw,bh)*0.5*(1-edge);
const gm = scx.createRadialGradient(bw/2,bh/2, r0, bw/2,bh/2, Math.hypot(bw,bh)*0.5*1.02);
gm.addColorStop(0,'rgba(255,255,255,0)');
gm.addColorStop(0.7,'rgba(255,255,255,'+(edge*0.85).toFixed(3)+')');
gm.addColorStop(1,'rgba(255,255,255,1)');
scx.fillStyle = gm; scx.fillRect(0,0,bw,bh);
scx.restore();
S.scr.blendMode(BLEND);
S.scr.pop();

// 4) lay the aberrated edge copy over the scene
blendMode(BLEND);
imageMode(CORNER);
image(S.scr, 0, 0, W, H);

// 5) self-driven chroma scanlines + tracking bands — the real-time motion floor
//    (the aberration is invisible over a flat field, so this MUST carry motion alone)
blendMode(ADD);
const gAmt = clamp(P.grain,0,1) * (st==='vhs' ? 1.6 : st==='xray' ? 0.6 : 1) + 0.28;
const rsat = clamp(P.sat,0,100);
// broad soft tracking bands scrolling at their own rate — big-area motion for the gate
for (let b=0;b<3;b++){
  const by = ((b/3)*H + K.t*(34+b*9)*P.speed) % (H+u*0.2) - u*0.1;
  const bh2 = u*(0.05+0.03*b);
  const g = dg.createLinearGradient(0,by-bh2,0,by+bh2);
  const bhue = (st==='xray')?0:(P.hue+b*40)%360, bsa=(st==='xray')?0:rsat*0.5;
  g.addColorStop(0,'hsla('+bhue+','+bsa+'%,80%,0)');
  g.addColorStop(0.5,'hsla('+bhue+','+bsa+'%,86%,'+(0.045+0.06*gAmt).toFixed(3)+')');
  g.addColorStop(1,'hsla('+bhue+','+bsa+'%,80%,0)');
  dg.save(); dg.fillStyle=g; dg.fillRect(0,by-bh2,W,bh2*2); dg.restore();
}
// fine RGB-split scanlines
const nL = 22, ls = ox*0.9 + u*0.006;
for (let i=0;i<nL;i++){
  const yy = ((i/nL)*H + K.t*26*P.speed + fr(i)*20) % (H+2) - 1;
  const a = (6 + 9*gAmt) * (0.55 + 0.45*Math.sin(K.t*2 + i)) * (0.8 + 0.4*beatKick);
  strokeWeight(1.4 + gAmt*1.4);
  stroke(0, (st==='xray')?0:rsat, (st==='xray')?92:100, a);
  line(-ls, yy, W-ls, yy);
  if (st!=='xray'){ stroke(240,rsat,100,a); line(ls, yy+1, W+ls, yy+1); }
}
// vhs rolling bright bar
if (st === 'vhs') {
  const by = (K.t*70*P.speed) % (H+u*0.3) - u*0.15;
  const g = dg.createLinearGradient(0,by-u*0.12,0,by+u*0.12);
  g.addColorStop(0,'hsla('+P.hue+',40%,80%,0)');
  g.addColorStop(0.5,'hsla('+P.hue+',30%,90%,'+(0.10+0.10*gAmt).toFixed(3)+')');
  g.addColorStop(1,'hsla('+P.hue+',40%,80%,0)');
  dg.save(); dg.fillStyle=g; dg.fillRect(0,by-u*0.12,W,u*0.24); dg.restore();
}

blendMode(BLEND);
noTint();
dg.shadowBlur = 0;
